package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.features.access.trustedclient.domain.AllowedLogoutRedirects;

class AllowedLogoutRedirectsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property allowed logout redirects of trusted client ")
  void test_allowed_logout_redirects_v_o_builder() {
    Assertions
        .assertTrue(AllowedLogoutRedirectsVO.tryFrom(null).getAllowedLogoutRedirects().isEmpty());
    List<AllowedLogoutRedirects> list = List.of();
    Assertions.assertEquals(list, AllowedLogoutRedirectsVO.from(list).getAllowedLogoutRedirects());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AllowedLogoutRedirectsVO.tryFrom(falingInstance));
    Assertions.assertEquals(
        "[" + List.of(AllowedLogoutRedirects.builder().uid("one").url("one").version(1).build())
            + "]",
        AllowedLogoutRedirectsVO
            .from(
                List.of(AllowedLogoutRedirects.builder().uid("one").url("one").version(1).build()))
            .toString());
  }
}
